 13→// droppedTypes are entry types that carry no parser-relevant data.
 14→var droppedTypes = map[string]bool{
 15→	"progress":              true,
 16→	"file-history-snapshot": true,
 17→	"queue-operation":       true,
 18→	"system":                true,
 19→}
 20→
 21→// CompactOptions provides metadata fields written to every output line.
 22→type CompactOptions struct {
 23→	Agent      string // e.g. "claude-code"
 24→	CLIVersion string // e.g. "0.42.0"
 25→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 26→}
 27→
 28→// compactMeta holds pre-computed JSON fragments for fields that are identical
 29→// on every output line, avoiding repeated marshaling.
 30→type compactMeta struct {
 31→	v          json.RawMessage
 32→	agent      json.RawMessage
 33→	cliVersion json.RawMessage
 34→}
 35→
 36→func newCompactMeta(opts CompactOptions) compactMeta {
 37→	return compactMeta{
 38→		v:          mustMarshal(1),
 39→		agent:      mustMarshal(opts.Agent),
 40→		cliVersion: mustMarshal(opts.CLIVersion),
 41→	}
 42→}
 43→
 44→// Compact converts a full.jsonl transcript into the transcript.jsonl format.
 45→//
 46→// The output format puts version, agent, and cli_version on every line,
 47→// flattens the message wrapper, and splits user tool results into separate entries:
 48→//
 49→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 50→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user_tool_result","ts":"...","tool_use_id":"...","result":{...}}
 51→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[...]}
 52→func Compact(content []byte, opts CompactOptions) ([]byte, error) {
 53→	truncated := SliceFromLine(content, opts.StartLine)
 54→	if truncated == nil {
 55→		truncated = []byte{}
 56→	}
 57→
 58→	meta := newCompactMeta(opts)
 59→	reader := bufio.NewReader(bytes.NewReader(truncated))
 60→	var result []byte
 61→
 62→	for {
 63→		lineBytes, err := reader.ReadBytes('\n')
 64→		if err != nil && err != io.EOF {
 65→			return nil, err
 66→		}
 67→
 68→		if len(bytes.TrimSpace(lineBytes)) > 0 {
 69→			outputLines := convertLine(lineBytes, meta)
 70→			for _, ol := range outputLines {
 71→				result = append(result, ol...)
 72→				result = append(result, '\n')
 73→			}
 74→		}
 75→
 76→		if err == io.EOF {
 77→			break
 78→		}
 79→	}
 80→
 81→	return result, nil
 82→}
 83→
 84→// userAliases maps transcript type/role values to the canonical "user" kind.
 85→var userAliases = map[string]bool{
 86→	TypeUser: true,
 87→	"human":  true,
 88→}
 89→
 90→// assistantAliases maps transcript type/role values to the canonical "assistant" kind.
 91→var assistantAliases = map[string]bool{
 92→	TypeAssistant: true,
 93→	"gemini":      true,
 94→}
 95→
 96→// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
 97→// transcript line. It checks the "type" field, then falls back to "role".
 98→// Returns "" for unrecognised or dropped entries.
 99→func normalizeKind(raw map[string]json.RawMessage) string {
100→	kind := unquote(raw["type"])
101→	if kind == "" {
102→		kind = unquote(raw["role"])
103→	}
104→
105→	if droppedTypes[kind] {
106→		return ""
107→	}
108→	if userAliases[kind] {
109→		return TypeUser
110→	}
111→	if assistantAliases[kind] {
112→		return TypeAssistant
113→	}
114→	return ""
115→}
116→
117→// unwrapEnvelope handles envelope formats where the actual message is nested.
118→// Factory AI Droid uses {"type":"message","message":{"role":"user","content":...}}.
119→// If the line is an envelope, it promotes inner fields (role, content) to the top
120→// level and carries over outer fields (timestamp, id) so converters see a flat structure.
121→// Otherwise it returns raw unchanged.
122→func unwrapEnvelope(raw map[string]json.RawMessage) map[string]json.RawMessage {
123→	if unquote(raw["type"]) != "message" {
124→		return raw
125→	}
126→
127→	msgRaw, ok := raw["message"]
128→	if !ok {
129→		return raw
130→	}
131→
132→	var inner map[string]json.RawMessage
133→	if json.Unmarshal(msgRaw, &inner) != nil {
134→		return raw
135→	}
136→
137→	innerRole := unquote(inner["role"])
138→	if !userAliases[innerRole] && !assistantAliases[innerRole] {
139→		return raw
140→	}
141→
142→	// Merge outer → inner: outer timestamp/id as defaults, inner fields override.
143→	merged := make(map[string]json.RawMessage, len(inner)+3)
144→	if v, has := raw["timestamp"]; has {
145→		merged["timestamp"] = v
146→	}
147→	if v, has := raw["id"]; has {
148→		merged["id"] = v
149→	}
150→	for k, v := range inner {
151→		merged[k] = v
152→	}
153→	// Promote "role" to "type" so normalizeKind resolves it.
154→	if _, hasType := merged["type"]; !hasType {
155→		merged["type"] = inner["role"]
156→	}
157→	// Keep "message" so converters can extract nested content.
158→	merged["message"] = msgRaw
159→
160→	return merged
161→}
162→
163→// convertLine converts a single full.jsonl line into zero or more transcript.jsonl lines.
164→func convertLine(lineBytes []byte, meta compactMeta) [][]byte {
165→	var raw map[string]json.RawMessage
166→	if err := json.Unmarshal(lineBytes, &raw); err != nil {
167→		return nil
168→	}
169→
170→	raw = unwrapEnvelope(raw)
171→
172→	switch normalizeKind(raw) {
173→	case TypeAssistant:
174→		return convertAssistant(raw, meta)
175→	case TypeUser:
176→		return convertUser(raw, meta)
177→	default:
178→		return nil
179→	}
180→}
181→
182→func convertAssistant(raw map[string]json.RawMessage, meta compactMeta) [][]byte {
183→	var id, content json.RawMessage
184→	if msg := parseMessage(raw); msg != nil {
185→		id = msg["id"]
186→		if contentRaw, ok := msg["content"]; ok {
187→			content = stripAssistantContent(contentRaw)
188→		}
189→	}
190→
191→	b := marshalOrdered(
192→		"v", meta.v,
193→		"agent", meta.agent,
194→		"cli_version", meta.cliVersion,
195→		"type", mustMarshal(TypeAssistant),
196→		"ts", raw["timestamp"],
197→		"id", id,
198→		"content", content,
199→	)
200→	if b == nil {
201→		return nil
202→	}
203→	return [][]byte{b}
204→}
205→
206→func convertUser(raw map[string]json.RawMessage, meta compactMeta) [][]byte {
207→	var lines [][]byte
208→	ts := raw["timestamp"]
209→
210→	var textContent string
211→	var toolResults []toolResultEntry
212→
213→	if msg := parseMessage(raw); msg != nil {
214→		if contentRaw, ok := msg["content"]; ok {
215→			textContent, toolResults = extractUserContent(contentRaw)
216→		}
217→	}
218→
219→	b := marshalOrdered(
220→		"v", meta.v,
221→		"agent", meta.agent,
222→		"cli_version", meta.cliVersion,
223→		"type", mustMarshal(TypeUser),
224→		"ts", ts,
225→		"content", mustMarshal(textContent),
226→	)
227→	if b != nil {
228→		lines = append(lines, b)
229→	}
230→
231→	// full.jsonl has a single toolUseResult per user entry, not one per tool_use_id.
232→	// When there are multiple tool_result blocks, each user_tool_result line gets the
233→	// same minimized result — a known limitation of the source format.
234→	var minimizedResult json.RawMessage
235→	if turRaw, ok := raw["toolUseResult"]; ok {
236→		minimizedResult = minimizeToolUseResult(turRaw)
237→	}
238→
239→	for _, tr := range toolResults {
240→		result := minimizedResult
241→		if result == nil {
242→			result = mustMarshal(map[string]interface{}{})
243→		}
244→
245→		b := marshalOrdered(
246→			"v", meta.v,
247→			"agent", meta.agent,
248→			"cli_version", meta.cliVersion,
249→			"type", mustMarshal("user_tool_result"),
250→			"ts", ts,
251→			"tool_use_id", mustMarshal(tr.toolUseID),
252→			"result", result,
253→		)
254→		if b != nil {
255→			lines = append(lines, b)
256→		}
257→	}
258→
259→	return lines
260→}
261→
262→type toolResultEntry struct {
263→	toolUseID string
264→}
265→
266→// parseMessage extracts and parses the "message" field from a transcript line.
267→func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
268→	msgRaw, ok := raw["message"]
269→	if ok {
270→		var msg map[string]json.RawMessage
271→		if json.Unmarshal(msgRaw, &msg) == nil {
272→			return msg
273→		}
274→	}
275→
276→	// Native Gemini transcript entries store id/content at top-level
277→	// rather than inside a nested "message" object.
278→	msg := make(map[string]json.RawMessage, 2)
279→	if v, has := raw["id"]; has {
280→		msg["id"] = v
281→	}
282→	if v, has := raw["content"]; has {
283→		msg["content"] = v
284→	}
285→	if len(msg) == 0 {
286→		return nil
287→	}
288→	return msg
289→}
290→
291→// extractUserContent separates user message content into text and tool_result entries.
292→// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
293→func extractUserContent(contentRaw json.RawMessage) (string, []toolResultEntry) {
294→	var str string
295→	if json.Unmarshal(contentRaw, &str) == nil {
296→		return textutil.StripIDEContextTags(str), nil
297→	}
298→
299→	var blocks []map[string]json.RawMessage
300→	if json.Unmarshal(contentRaw, &blocks) != nil {
301→		return "", nil
302→	}
303→
304→	var texts []string
305→	var toolResults []toolResultEntry
306→
307→	for _, block := range blocks {
308→		blockType := unquote(block["type"])
309→
310→		if blockType == "tool_result" {
311→			toolResults = append(toolResults, toolResultEntry{
312→				toolUseID: unquote(block["tool_use_id"]),
313→			})
314→			continue
315→		}
316→
317→		if blockType == ContentTypeText {
318→			stripped := textutil.StripIDEContextTags(unquote(block[ContentTypeText]))
319→			if stripped != "" {
320→				texts = append(texts, stripped)
321→			}
322→		}
323→	}
324→
325→	return strings.Join(texts, "\n\n"), toolResults
326→}
327→
328→func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
329→	var str string
330→	if json.Unmarshal(contentRaw, &str) == nil {
331→		return contentRaw
332→	}
333→
334→	var blocks []map[string]json.RawMessage
335→	if json.Unmarshal(contentRaw, &blocks) != nil {
336→		return contentRaw
337→	}
338→
339→	var result []map[string]json.RawMessage
340→	for _, block := range blocks {
341→		blockType := unquote(block["type"])
342→
343→		if blockType == "thinking" || blockType == "redacted_thinking" {
344→			continue
345→		}
346→
347→		if blockType == ContentTypeToolUse {
348→			stripped := make(map[string]json.RawMessage)
349→			copyField(stripped, block, "type")
350→			copyField(stripped, block, "id")
351→			copyField(stripped, block, "name")
352→			copyField(stripped, block, "input")
353→			result = append(result, stripped)
354→			continue
355→		}
356→
357→		result = append(result, block)
358→	}
359→
360→	b, err := json.Marshal(result)
361→	if err != nil {
362→		return contentRaw
363→	}
364→	return b
365→}
366→
367→// minimizeToolUseResult keeps only fields needed for replaying tool calls
368→// (type, file metadata, error, answers). Output text and other verbose
369→// fields are dropped to reduce transcript size.
370→func minimizeToolUseResult(raw json.RawMessage) json.RawMessage {
371→	var obj map[string]json.RawMessage
372→	if json.Unmarshal(raw, &obj) != nil {
373→		return raw
374→	}
375→
376→	return marshalOrdered(
377→		"type", obj["type"],
378→		"file", obj["file"],
379→		"error", obj["error"],
380→		"answers", obj["answers"],
381→	)
382→}
383→
384→// marshalOrdered produces a JSON object with keys in the given order.
385→// Pairs with nil values are omitted.
386→func marshalOrdered(pairs ...interface{}) []byte {
387→	var buf bytes.Buffer
388→	buf.WriteByte('{')
389→	first := true
390→	for i := 0; i < len(pairs)-1; i += 2 {
391→		key := pairs[i].(string)
392→		val, _ := pairs[i+1].(json.RawMessage)
393→		if val == nil {
394→			continue
395→		}
396→		if !first {
397→			buf.WriteByte(',')
398→		}
399→		keyJSON, _ := json.Marshal(key)
400→		buf.Write(keyJSON)
401→		buf.WriteByte(':')
402→		buf.Write(val)
403→		first = false
404→	}
405→	buf.WriteByte('}')
406→	return buf.Bytes()
407→}
408→
409→func mustMarshal(v interface{}) json.RawMessage {
410→	b, _ := json.Marshal(v)
411→	return b
412→}
413→
414→func copyField(dst, src map[string]json.RawMessage, key string) {
415→	if v, ok := src[key]; ok {
416→		dst[key] = v
417→	}
418→}
419→
420→func unquote(raw json.RawMessage) string {
421→	var s string
422→	if json.Unmarshal(raw, &s) == nil {
423→		return s
424→	}
425→	return ""
426→}
